insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jm-7', 'Deteriorating economic conditions during the 1970s led to recurring violence as rival gangs affiliated with the major political parties evolved into powerful organized crime networks involved in international drug smuggling and money laundering.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JAMAICA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jm/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jm/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jm-8', 'Violent crime, drug trafficking, corruption, and poverty pose significant challenges to the government today.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JAMAICA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jm/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jm/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jm-9', 'Nonetheless, many rural and resort areas remain relatively safe and contribute substantially to the economy.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JAMAICA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jm/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jm/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jn-0', 'This desolate, mountainous island in the Arctic Ocean was named after a Dutch whaling captain who indisputably discovered it in 1614 (earlier claims are inconclusive).', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JANMAYEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jn-1', 'Visited only occasionally by seal hunters and trappers over the centuries, the island came under Norwegian sovereignty in 1929.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JANMAYEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jn-2', 'The long dormant Beerenberg volcano, the northernmost active volcano on earth, resumed activity in 1970, and the most recent eruption occurred in 1985.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JANMAYEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-0', 'Amman is the capital of Jordan.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-1', 'After World War I and the dissolution of the Ottoman Empire, the League of Nations awarded Britain the mandate to govern much of the Middle East.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-10', 'Jordanian kings claim custodianship of the Christian sites in Jerusalem on the basis of the 7th-century Pact of Omar, when the Muslim leader, after conquering Jerusalem, agreed to permit Christian worship.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-11', 'King HUSSEIN died in 1999 and was succeeded by his eldest son and current King ABDALLAH II.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-12', 'In 2009, ABDALLAH II designated his son HUSSEIN as the Crown Prince.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-13', 'During his reign, ABDALLAH II has contended with a series of challenges, including the Arab Spring influx of refugees from neighboring states, the COVID-19 pandemic, the effects of the war in Ukraine, a perennially weak economy, and the Israel-HAMAS conflict that began in October 2023.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-2', 'In 1921, Britain demarcated from Palestine a semi-autonomous region of Transjordan and recognized ABDALLAH I from the Hashemite family as the country''s first leader.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-3', 'The Hashemites also controlled the Hijaz, or the western coastal area of modern-day Saudi Arabia, until 1925, when IBN SAUD and Wahhabi tribes pushed them out.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-4', 'The country gained its independence in 1946 and thereafter became the Hashemite Kingdom of Jordan.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-5', 'In 1948, Jordan took control of the West Bank and East Jerusalem in the first Arab-Israeli War, eventually annexing those territories in 1950 and granting its new Palestinian residents Jordanian citizenship.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-6', 'In 1967, Jordan lost the West Bank and East Jerusalem to Israel in the Six-Day War but retained administrative claims to the West Bank until 1988, when King HUSSEIN permanently relinquished Jordanian claims to the West Bank in favor of the Palestine Liberation Organization (PLO).', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-7', 'King HUSSEIN signed a peace treaty with Israel in 1994, after Israel and the PLO signed the Oslo Accords in 1993.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-8', 'Jordanian kings continue to claim custodianship of the Muslim holy sites in Jerusalem by virtue of their Hashemite heritage as descendants of the Prophet Mohammad and agreements with Israel and Jerusalem-based religious and Palestinian leaders.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-jo-9', 'After Israel captured East Jerusalem in the 1967 War, it authorized the Jordanian-controlled Islamic Trust, or Waqf, to continue administering the Al Haram ash Sharif/Temple Mount holy compound, and the Jordan-Israel peace treaty reaffirmed Jordan''s "special role" in administering the Muslim holy shrines in Jerusalem.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.JORDAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/jo/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/jo/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-0', 'Nairobi is the capital of Kenya.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-1', 'Trade centers such as Mombasa have existed along the Kenyan and Tanzanian coastlines, known as the Land of Zanj, since at least the 2nd century.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-10', 'The country was a de facto one-party state from 1969 until 1982, after which time the ruling Kenya African National Union (KANU) changed the constitution to make itself the sole legal political party.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-11', 'MOI gave in to internal and external pressure for political liberalization in 1991, but the ethnically fractured opposition failed to dislodge KANU from power in elections in 1992 and 1997, which were marred by violence and fraud.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-12', 'Mwai KIBAKI, running as the candidate of the multiethnic, united opposition group, the National Rainbow Coalition (NARC), defeated KANU candidate Uhuru KENYATTA, the son of the founding president, and assumed the presidency following a campaign centered on an anticorruption platform.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-13', 'Opposition candidate Raila ODINGA challenged KIBAKI''s reelection in 2007 on the grounds of widespread vote rigging, leading to two months of ethnic violence that caused more than 1,100 deaths and displaced hundreds of thousands.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-14', 'African Union-sponsored mediation resulted in a power-sharing accord that brought ODINGA into the government as prime minister and outlined a reform agenda.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-15', 'In 2010, Kenyans overwhelmingly voted to adopt a new constitution that eliminated the prime minister, introduced additional checks and balances to executive power, and devolved power and resources to 47 newly created counties.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-16', 'Uhuru KENYATTA won the first presidential election under the new constitution in 2013.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-17', 'He won a second and final term in office in 2017 after a contentious repeat election.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-18', 'In 2022, William RUTO won a close presidential election; he assumed the office the following month after the Kenyan Supreme Court upheld the victory.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-2', 'These centers traded with the outside world, including China, India, Indonesia, the Middle East, North Africa, and Persia.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-3', 'By around the 9th century, the mix of Africans, Arabs, and Persians who lived and traded there became known as Swahili ("people of the coast") with a distinct language (KiSwahili) and culture.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-4', 'The Portuguese arrived in the 1490s and, using Mombasa as a base, sought to monopolize trade in the Indian Ocean.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-5', 'The Portuguese were pushed out in the late 1600s by the combined forces of Oman and Pate, an island off the coast.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-6', 'In 1890, Germany and the UK divided up the region, with the UK taking the north and the Germans the south, including present-day Tanzania, Burundi, and Rwanda.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-7', 'In 1895, the British established the East Africa Protectorate, which in 1920 was converted into a colony, and named Kenya after its highest mountain.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-8', 'Numerous political disputes between the colony and the UK led to the violent Mau Mau Uprising, which began in 1952, and the eventual declaration of independence in 1963.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ke-9', 'Jomo KENYATTA, the founding president and an icon of the liberation struggle, led Kenya from independence in 1963 until his death in 1978, when Vice President Daniel Arap MOI took power in a constitutional succession.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KENYA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ke/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ke/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kg-0', 'Bishkek is the capital of Kyrgyzstan.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KYRGYZSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kg-1', 'Kyrgyzstan is a Central Asian country of incredible natural beauty and proud nomadic traditions.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KYRGYZSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kg-10', 'In 2021, Kyrgyzstanis voted in favor of constitutional changes that consolidated power in the presidency.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KYRGYZSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kg-11', 'Pro-government parties won a majority in the 2021 legislative elections.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KYRGYZSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kg-12', 'Continuing concerns for Kyrgyzstan include the trajectory of democratization, endemic corruption, tense regional relations, vulnerabilities due to climate change, border security vulnerabilities, and potential terrorist threats.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KYRGYZSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kg-2', 'The Russian Empire annexed most of the territory of present-day Kyrgyzstan in 1876.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KYRGYZSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kg-3', 'The Kyrgyz staged a major revolt against the Tsarist Empire in 1916, during which almost one-sixth of the Kyrgyz population was killed.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KYRGYZSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kg-4', 'Kyrgyzstan became a Soviet republic in 1926 and achieved independence in 1991 when the USSR dissolved.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KYRGYZSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kg-5', 'Nationwide demonstrations in 2005 and 2010 resulted in the ouster of the country’s first two presidents, Askar AKAEV and Kurmanbek BAKIEV.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KYRGYZSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kg-6', 'In 2017, ATAMBAEV became the first Kyrgyzstani president to serve a full term and respect constitutional term limits, voluntarily stepping down at the end of his mandate.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KYRGYZSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kg-7', 'Former prime minister and ruling Social-Democratic Party of Kyrgyzstan member Sooronbay JEENBEKOV replaced him after winning the 2017 presidential election, which was the most competitive in the country’s history despite reported cases of vote buying and abuse of public resources.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KYRGYZSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kg-8', 'In 2020, protests against parliamentary election results spread across Kyrgyzstan, leading to JEENBEKOV’s resignation and catapulting previously imprisoned Sadyr JAPAROV to acting president.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KYRGYZSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kg-9', 'In 2021, Kyrgyzstanis formally elected JAPAROV as president and approved a referendum to move Kyrgyzstan from a parliamentary to a presidential system.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KYRGYZSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-0', 'Pyongyang is the capital of North Korea.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-1', 'Over the subsequent centuries, three main kingdoms -- Kogoryo, Paekche, and Silla -- were established on the Peninsula.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-10', 'KIM''s authoritarian rule included tight control over North Korean citizens and the demonization of the US as the central threat to North Korea''s political and social system.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-11', 'In addition, he molded the country''s economic, military, and political policies around the core objective of unifying Korea under Pyongyang''s control.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-12', 'North Korea also declared a central ideology of juche (" self-reliance") as a check against outside influence, while continuing to rely heavily on China and the Soviet Union for economic support.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-13', 'KIM Il Sung''s son, KIM Jong Il, was officially designated as his father''s successor in 1980, and he assumed a growing political and managerial role until the elder KIM''s death in 1994.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-14', 'Under KIM Jong Il''s reign, North Korea continued developing nuclear weapons and ballistic missiles.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-15', 'KIM Jong Un was publicly unveiled as his father''s successor in 2010.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-16', 'Following KIM Jong Il''s death in 2011, KIM Jong Un quickly assumed power and has since occupied the regime''s highest political and military posts.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-17', 'After the end of Soviet aid in 1991, North Korea faced serious economic setbacks that exacerbated decades of economic mismanagement and resource misallocation.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-18', 'Since the mid-1990s, North Korea has faced chronic food shortages and economic stagnation.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-19', 'In recent years, the North''s domestic agricultural production has improved but still falls far short of producing sufficient food for its population.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-2', 'By the 5th century A.D., Kogoryo emerged as the most powerful, with control over much of the Peninsula and part of Manchuria (modern-day northeast China).', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-20', 'Starting in 2002, North Korea began to tolerate semi-private markets but has made few other efforts to meet its goal of improving the overall standard of living.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-21', 'New economic development plans in the 2010s failed to meet government-mandated goals for key industrial sectors, food production, or overall economic performance.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-22', 'At the onset of the COVID-19 pandemic in 2020, North Korea instituted a nationwide lockdown that severely restricted its economy and international engagement.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-23', 'Since then, KIM has repeatedly expressed concerns with the regime''s economic failures and food problems, but in 2021, he vowed to continue "self-reliant" policies and has reinvigorated his pursuit of greater regime control of the economy.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-24', 'As of 2024, despite slowly renewing cross-border trade with China, North Korea remained one of the world''s most isolated countries and one of Asia''s poorest.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-25', 'In 2024, Pyongyang announced it was ending all economic cooperation with South Korea.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-3', 'However, Silla allied with the Chinese to create the first unified Korean state in 688.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-4', 'Following the collapse of Silla in the 9th century, Korea was unified under the Koryo (Goryeo; 918-1392) and the Chosen (Joseon; 1392-1910) dynasties.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-5', 'Korea became the object of intense imperialistic rivalry among the Chinese (its traditional benefactor), Japanese, and Russian empires in the latter half of the 19th and early 20th centuries.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-6', 'After the Sino-Japanese War (1894-95) and the Russo-Japanese War (1904-05), Korea was occupied by Imperial Japan.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-7', 'After World War II, the northern half came under Soviet-sponsored communist control.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-8', 'In 1948, North Korea (formally known as the Democratic People''s Republic of Korea or DPRK) was founded under President KIM Il Sung, who consolidated power and cemented autocratic one-party rule under the Korean Worker''s Party (KWP).', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kn-9', 'North Korea failed to conquer UN-backed South Korea (formally the Republic of Korea or ROK) during the Korean War (1950-53), after which a demilitarized zone separated the two Koreas.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-0', 'Tarawa is the capital of Kiribati.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-1', 'Kiribati is made up of three distinct island groups -- the Gilbert Islands, the Line Islands, and the Phoenix Islands.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-10', 'The Phoenix Islands were added to the colony in 1937, and the UK agreed to share jurisdiction of some with the US because of their strategic location for aviation.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-11', 'During World War II, the islands were occupied by Japanese forces but were ejected by US amphibious assaults.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-12', 'The Ellice Islands became its own colony in 1974 and was renamed Tuvalu for “eight standing together” in 1975.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-13', 'The Gilbert Islands became fully self-governing in 1977 and independent in 1979 under the new name of Kiribati, the Gilbertese spelling of Gilberts.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-14', 'The US relinquished all claims to the sparsely inhabited Phoenix and Line Islands in a 1979 treaty of friendship.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-15', 'In 2012, Kiribati purchased a 22 sq km (8.5 sq mi) plot of land in Fiji for potential eventual resettlement of its population because of climate change, and in 2014 Fijian Prime Minister Voreqe BAINIMARAMA said residents of Kiribati would be welcome to relocate to Fiji if their country is swamped by rising sea levels.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-2', 'Around 1300, Samoans and Tongans invaded the southern Gilbert Islands, then known as Tungaru, bringing Polynesian cultural elements with them.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-3', 'Later arrivals of Fijians brought Melanesian elements to the Gilbert Islands, and extensive intermarriage between the Micronesian, Polynesian, and Melanesian people led to the creation of what would become Gilbertese cultural traditions by the time Europeans spotted the islands in the 1600s.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-4', 'The Phoenix Islands and Line Islands were both visited by various Melanesian and Polynesian peoples, but their isolation and lack of natural resources meant that long-term settlements were not possible.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-5', 'Both island groups were uninhabited by the time of European contact.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-6', 'Kiribati experienced sustained European contact by the 1760s; all three island groups were named and charted by 1826.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-7', 'American whaling ships frequently passed through the islands, and the UK declared a protectorate over the Gilbert and nearby Ellice Islands in 1892, in an attempt to block growing US influence.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-8', 'Phosphate-rich Banaba Island was annexed to the protectorate in 1900.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kr-9', 'In 1916, the protectorate became a colony, and some Line Islands were added in 1916 and 1919, with the final ones added in 1972.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KIRIBATI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kr/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kr/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-0', 'Seoul is the capital of South Korea.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-1', 'Over the subsequent centuries, three main kingdoms -- Kogoryo, Baekche, and Silla -- were established on the Peninsula.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-10', 'After the 1953 armistice, the two Koreas were separated by a demilitarized zone.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-11', 'Syngman RHEE led the country as its first president from 1948 to 1960.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-12', 'PARK Chung-hee took over leadership of the country in a 1961 coup.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-13', 'During his controversial rule (1961-79), South Korea achieved rapid economic growth, with per capita income rising to roughly 17 times the level of North Korea by 1979.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-14', 'PARK was assassinated in 1979, and subsequent years were marked by political turmoil and continued military rule as the country''s pro-democracy movement grew.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-15', 'South Korea held its first free presidential election under a revised democratic constitution in 1987, with former South Korean Army general ROH Tae-woo winning a close race.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-16', 'In 1993, KIM Young-sam became the first civilian president of South Korea''s new democratic era.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-17', 'President KIM Dae-jung (1998-2003) won the Nobel Peace Prize in 2000 for his contributions to South Korean democracy and his "Sunshine Policy" of engagement with North Korea.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-18', 'President PARK Geun-hye, daughter of former South Korean President PARK Chung-hee, took office in 2013 as South Korea''s first female leader.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-19', 'In 2016, the National Assembly passed an impeachment motion against PARK over her alleged involvement in a corruption and influence-peddling scandal, triggering an early presidential election in 2017 won by MOON Jae-in.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-20', 'In 2022, longtime prosecutor and political newcomer YOON Suk Yeol won the presidency by the slimmest margin in South Korean history.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-21', 'Discord and tensions with North Korea, punctuated by North Korean military provocations, missile launches, and nuclear tests, have permeated inter-Korean relations for years.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-22', 'Relations remained strained, despite a period of respite in 2018-2019 ushered in by North Korea''s participation in the 2018 Winter Olympic and Paralympic Games in South Korea and high-level diplomatic meetings, including historic US-North Korea summits.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-6', 'After the Sino-Japanese War (1894-95) and the Russo-Japanese War (1904-1905), Korea was occupied by Imperial Japan.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-7', 'Korea regained its independence after Japan''s surrender to the US and its allies in 1945.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-8', 'A US-supported democratic government (Republic of Korea, ROK) was set up in the southern half of the Korean Peninsula, while a communist-style government backed by the Soviet Union was installed in the north (North Korea; aka Democratic People''s Republic of Korea, DPRK).', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ks-9', 'During the Korean War (1950-53), US troops and UN forces fought alongside ROK soldiers to defend South Korea from a North Korean invasion supported by communist China and the Soviet Union.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SOUTHKOREA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ks/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ks/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kt-0', 'The Settlement (Flying Fish Cove) is the capital of Christmas Island.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.CHRISTMASISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kt-1', 'Although Europeans sighted Christmas Island in 1615, it was named for the day of its rediscovery in 1643.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.CHRISTMASISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kt-10', 'In 2001, Australia declared Christmas Island to be outside the Australian migration zone and built an immigration detention center on the island.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.CHRISTMASISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kt-11', 'Completed in 2008, the controversial detention center was closed in 2018 but then reopened in 2019.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.CHRISTMASISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kt-12', 'In 2020, the center served as a coronavirus quarantine facility for Australian citizens evacuated from China.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.CHRISTMASISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kt-2', 'Steep cliffs and dense jungle hampered attempts to explore the island over the next two centuries.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.CHRISTMASISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kt-3', 'The discovery of phosphate on the island in 1887 led to the UK annexing it the following year.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.CHRISTMASISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kt-4', 'In 1898, 200 Chinese indentured servants were brought in to work the mines, along with Malays, Sikhs, and a small number of Europeans.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.CHRISTMASISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kt-5', 'Japan invaded the island in 1942, but islanders sabotaged Japanese mining operations, making the mines relatively unproductive.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.CHRISTMASISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kt-6', 'After World War II, Australia and New Zealand bought the company mining the phosphate, and in 1958, the UK transferred sovereignty from Singapore to Australia in exchange for $20 million to compensate for the loss of future phosphate income.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.CHRISTMASISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kt-7', 'In 1980, Australia set up the Christmas Island National Park and expanded its boundaries throughout the 1980s until it covered more than 60% of the island’s territory.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.CHRISTMASISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kt-8', 'The phosphate mine was closed in 1987 because of environmental concerns, and Australia has rejected several efforts to reopen it.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.CHRISTMASISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kt-9', 'In the 1980s, boats of asylum seekers started landing on Christmas Island, and the migrants claimed refugee status because they were on Australian territory.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.CHRISTMASISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-0', 'Kuwait City is the capital of Kuwait.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-1', 'Kuwait has been ruled by the AL-SABAH dynasty since the 18th century.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-10', 'Between 2006 and his death in 2020, the Amir dissolved the National Assembly on seven occasions and shuffled the cabinet over a dozen times, usually citing political stagnation and gridlock between the legislature and the government.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-11', 'The current Amir, who assumed his role in 2020, launched a "National Dialogue" in 2021 meant to resolve political gridlock.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-12', 'As part of this initiative, the Amir pardoned several opposition figures who had been living in exile, and they returned to Kuwait.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-13', 'Legislative challenges remain, and the cabinet has been reshuffled six times since 2020.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-2', 'The threat of Ottoman invasion in 1899 prompted Amir Mubarak AL-SABAH to seek protection from Britain, ceding foreign and defense responsibility to Britain until 1961, when the country attained its independence.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-3', 'After several weeks of aerial bombardment, a US-led UN coalition began a ground assault in 1991 that liberated Kuwait in four days.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-4', 'In 1992, the Amir reconstituted the parliament that he had dissolved in 1986.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-5', 'Amid the 2010-11 uprisings and protests across the Arab world, stateless Arabs known as Bidoon staged small protests demanding citizenship, jobs, and other benefits available to Kuwaiti nationals.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-6', 'Other demographic groups, notably Islamists and Kuwaitis from tribal backgrounds, soon joined the growing protest movements, which culminated with the resignation of the prime minister amid allegations of corruption.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-7', 'Demonstrations renewed in 2012 in response to a decree amending the electoral law that lessened the voting power of the tribal blocs.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-8', 'An opposition coalition of Sunni Islamists, tribal populists, and some liberals largely boycotted legislative elections in 2012 and 2013, which ushered in a legislature more amenable to the government''s agenda.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ku-9', 'Faced with the prospect of painful subsidy cuts, oppositionists and independents actively participated in the 2016 election, winning nearly half the seats, but the opposition became increasingly factionalized.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KUWAIT"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ku/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ku/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-0', 'Pristina (Prishtine, Prishtina) is the capital of Kosovo.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-1', 'The Ottoman Empire took control of Kosovo in 1389 after defeating Serbian forces.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-10', 'Negotiations in 2006-07 ended without agreement between Serbia and Kosovo, though the UN issued a comprehensive report that endorsed independence.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-11', 'On 17 February 2008, the Kosovo Assembly declared Kosovo independent.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-12', 'Serbia continues to reject Kosovo''s independence, but the two countries began EU-facilitated discussions in 2013 to normalize relations, which resulted in several agreements.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-13', 'Additional agreements were reached in 2015 and 2023, but implementation remains incomplete.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-14', 'In 2022, Kosovo formally applied for membership in the EU, which is contingent on fulfillment of accession criteria, and the Council of Europe.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-2', 'Large numbers of Turks and Albanians moved to the region, and by the end of the 19th century, Albanians had replaced Serbs as the majority ethnic group in Kosovo.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-3', 'Serbia reacquired control of Kosovo during the First Balkan War of 1912, and after World War II, Kosovo became an autonomous province of Serbia in the Socialist Federal Republic of Yugoslavia (SFRY).', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-4', 'Increasing Albanian nationalism in the 1980s led to riots and calls for Kosovo''s independence, but in 1989, Belgrade -- which has in turn served as the capital of Serbia and Yugoslavia -- revoked Kosovo''s autonomous status.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-5', 'When the SFRY broke up in 1991, Kosovo Albanian leaders organized an independence referendum, and Belgrade''s repressive response led to an insurgency.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-6', 'Kosovo remained part of Serbia, which joined with Montenegro to declare a new Federal Republic of Yugoslavia (FRY) in 1992.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-7', 'In 1998, Belgrade launched a brutal counterinsurgency campaign, with some 800,000 ethnic Albanians expelled from their homes in Kosovo.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-8', 'After international mediation failed, a NATO military operation began in March 1999 and forced Belgrade to withdraw its forces from Kosovo.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kv-9', 'UN Security Council Resolution 1244 (1999) placed Kosovo under the temporary control of the UN Interim Administration Mission in Kosovo (UNMIK).', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KOSOVO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kz-0', 'Astana is the capital of Kazakhstan.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KAZAKHSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kz-1', 'Ethnic Kazakhs derive from a mix of Turkic nomadic tribes that migrated to the region in the 15th century.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KAZAKHSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kz-2', 'The Russian Empire conquered the Kazakh steppe in the 18th and 19th centuries, and Kazakhstan became a Soviet Republic in 1925.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KAZAKHSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kz-3', 'Forced agricultural collectivization led to repression and starvation, resulting in more than a million deaths in the early 1930s.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KAZAKHSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kz-4', 'During the 1950s and 1960s, the agricultural "Virgin Lands" program generated an influx of settlers -- mostly ethnic Russians, but also other nationalities -- and by the time of Kazakhstan’s independence in 1991, ethnic Kazakhs were a minority.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KAZAKHSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kz-5', 'However, non-Muslim ethnic minorities departed Kazakhstan in large numbers from the mid-1990s through the mid-2000s, and a national program has repatriated about a million ethnic Kazakhs (from Uzbekistan, Tajikistan, Mongolia, and the Xinjiang region of China) to Kazakhstan.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KAZAKHSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kz-6', 'As a result of this shift, the ethnic Kazakh share of the population now exceeds two-thirds.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KAZAKHSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kz-7', 'Kazakhstan''s economy is the largest in Central Asia, mainly due to the country''s vast natural resources.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KAZAKHSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-kz-8', 'Current issues include diversifying the economy, attracting foreign direct investment, enhancing Kazakhstan''s economic competitiveness, and strengthening economic relations with neighboring states and foreign powers.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.KAZAKHSTAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/kz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/kz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-la-0', 'Vientiane (Viangchan) is the capital of Laos.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LAOS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/la/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/la/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-la-1', 'Modern-day Laos has its roots in the ancient Lao kingdom of Lan Xang, established in the 14th century under King FA NGUM.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LAOS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/la/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/la/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-la-10', 'China, for example, provided 70% of the funding for a $5.9 billion, 400-km railway line between the Chinese border and the capital Vientiane, which opened for operations in 2021.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LAOS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/la/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/la/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-la-11', 'At the same time, Laos has expanded its economic reliance on the West and other Asian countries, such as Japan, Malaysia, Singapore, Taiwan, and Thailand.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LAOS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/la/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/la/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-la-12', 'Nevertheless, despite steady economic growth for more than a decade, it remains one of Asia''s poorest countries.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LAOS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/la/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/la/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-la-2', 'For 300 years, Lan Xang had influence reaching into present-day Cambodia and Thailand, as well as over all of what is now Laos.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LAOS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/la/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/la/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-la-3', 'After centuries of gradual decline, Laos came under the domination of Siam (Thailand) from the late 18th century until the late 19th century, when it became part of French Indochina.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LAOS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/la/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/la/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-la-4', 'The Franco-Siamese Treaty of 1907 defined the current Lao border with Thailand.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LAOS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/la/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/la/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-la-5', 'Following more than 15 years of civil war, the communist Pathet Lao took control of the government in 1975, ending a six-century-old monarchy and instituting a one party--the Lao People''s Revolutionary Party--communist state.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LAOS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/la/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/la/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-la-6', 'A gradual, limited return to private enterprise and the liberalization of foreign investment laws began in the late 1980s.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LAOS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/la/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/la/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-la-7', 'In the 2010s, the country benefited from direct foreign investment, particularly in the natural resource and industry sectors.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LAOS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/la/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/la/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-la-8', 'Construction of a number of large hydropower dams and expanding mining activities have also boosted the economy.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LAOS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/la/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/la/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-la-9', 'Laos has retained its official commitment to communism and maintains close ties with its two communist neighbors, Vietnam and China, both of which continue to exert substantial political and economic influence on the country.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LAOS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/la/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/la/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-le-0', 'Beirut is the capital of Lebanon.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LEBANON"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/le/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/le/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-le-1', 'As a result of its location at the crossroads of three continents, the area that is modern-day Lebanon is rich in cultural and religious diversity.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LEBANON"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/le/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/le/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-le-10', 'Hizballah -- a major Lebanese political party, militia, and US-designated foreign terrorist organization -- and Israel continued attacks and counterattacks against each other after Syria''s withdrawal and fought a brief war in 2006.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LEBANON"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/le/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/le/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-le-11', 'After HAMAS attacked Israel on 7 October 2023, the intensity and frequency of these cross-border attacks increased substantially into a cycle of hostilities, mostly limited to the border areas as of January 2024.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LEBANON"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/le/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/le/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-le-12', 'Lebanon''s prosperity has significantly diminished since the beginning of the country''s economic crisis in 2019, which has crippled its economy, shut down its previously lucrative banking sector, reduced the value of its currency, and caused many Lebanese to emigrate in search of better prospects.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LEBANON"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/le/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/le/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-le-2', 'This region was subject to various foreign conquerors for much of its history, including the Romans, Arabs, and Ottomans.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LEBANON"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/le/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/le/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-le-3', 'Following World War I, France acquired a mandate over the northern portion of the former Ottoman Empire province of Syria.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LEBANON"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/le/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/le/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-le-4', 'From it the French demarcated the region of Lebanon in 1920, and it gained independence in 1943.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LEBANON"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/le/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/le/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-le-5', 'Lebanon subsequently experienced periods of political turmoil interspersed with prosperity built on its position as a regional center for finance and trade.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LEBANON"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/le/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/le/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-le-6', 'The country''s 1975-90 civil war, which resulted in an estimated 120,000 fatalities, was followed by years of social and political instability, and sectarianism remains a key element of Lebanese political life.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LEBANON"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/le/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/le/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-le-7', 'The Israeli defense forces, which occupied parts of Lebanon during the civil war, did not completely withdraw until 2000.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LEBANON"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/le/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/le/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-le-8', 'Neighboring Syria influenced Lebanon''s foreign and domestic policies while its military occupied Lebanon from 1976 until 2005, but its influence diminished significantly after 2005.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LEBANON"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/le/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/le/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-le-9', 'Over 1.5 million Syrian refugees fled to Lebanon after the start of the Syrian conflict in 2011.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LEBANON"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/le/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/le/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-lg-0', 'Riga is the capital of Latvia.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LATVIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/lg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/lg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-lg-1', 'Several eastern Baltic tribes merged in medieval times to form the ethnic core of the Latvian people (ca.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LATVIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/lg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/lg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-lg-2', 'The region subsequently came under the control of Germans, Poles, Swedes, and finally Russians.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LATVIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/lg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/lg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-lg-3', 'A Latvian republic emerged following World War I, but the USSR annexed it in 1940 -- an action never recognized by the US and many other countries.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LATVIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/lg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/lg/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-lg-4', 'Latvia reestablished its independence in 1991 after the breakup of the Soviet Union.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LATVIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/lg/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/lg/', 'factbook.json') on conflict (anchor_id) do nothing;
