insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-lh-1', 'Lithuanian lands were united under MINDAUGAS in 1236; over the next century, Lithuania extended its territory through alliances and conquest to include most of present-day Belarus and Ukraine.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.LITHUANIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/lh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/lh/', 'factbook.json') on conflict (anchor_id) do nothing;
