insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mt-0', 'Valletta is the capital of Malta.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALTA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mt-1', 'With a civilization that dates back thousands of years, Malta boasts some of the oldest megalithic sites in the world.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALTA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mt-2', 'Situated in the center of the Mediterranean, Malta’s islands have long served as a strategic military asset, with the islands at various times falling under the control of the Phoenicians, Carthaginians, Greeks, Romans, Byzantines, Moors, Normans, Sicilians, Spanish, Knights of St.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALTA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mt-3', 'Most recently a British colony (since 1814), Malta gained its independence in 1964 and declared itself a republic 10 years later.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALTA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mt-4', 'While under British rule, the island staunchly supported the UK through both world wars.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALTA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mt-5', 'Since the mid-1980s, the island has transformed itself into a freight transshipment point, a financial center, and a tourist destination, as its key industries moved toward more service-oriented activities.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALTA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mt-6', 'Malta became an EU member in 2004 and joined the eurozone in 2008.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALTA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mt/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mt/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mu-0', 'Muscat is the capital of Oman.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.OMAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mu/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mu/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mu-1', 'The inhabitants of the area of present-day Oman have long prospered from Indian Ocean trade.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.OMAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mu/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mu/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mu-10', 'As part of the government''s efforts to decentralize authority and allow greater citizen participation in local governance, Oman successfully conducted its first municipal council elections in 2012.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.OMAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mu/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mu/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mu-11', 'His cousin, HAYTHAM bin Tariq Al Said, former Minister of Heritage and Culture, was sworn in as Oman''s new sultan the same day.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.OMAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mu/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mu/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mu-2', 'In the late 18th century, the nascent sultanate in Muscat signed the first in a series of friendship treaties with Britain.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.OMAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mu/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mu/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mu-3', 'Over time, Oman''s dependence on British political and military advisors increased, although the sultanate never became a British colony.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.OMAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mu/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mu/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mu-4', 'In 1970, QABOOS bin Said Al Said overthrew his father and ruled as sultan for the next five decades.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.OMAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mu/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mu/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mu-5', 'His extensive modernization program opened the country to the outside world.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.OMAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mu/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mu/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mu-6', 'He prioritized strategic ties to the UK and US, and his moderate, independent foreign policy allowed Oman to maintain good relations with its neighbors and avoid external entanglements.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.OMAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mu/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mu/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mu-7', 'In 2011, the popular uprisings that swept the Middle East and North Africa inspired demonstrations in Oman that called for more jobs and economic benefits and an end to corruption.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.OMAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mu/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mu/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mu-8', 'In response, QABOOS implemented economic and political reforms such as granting Oman’s legislative body more power and authorizing direct elections for its lower house.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.OMAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mu/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mu/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mu-9', 'Additionally, the sultan increased unemployment benefits and issued a royal directive mandating a national public- and private-sector job creation plan.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.OMAN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mu/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mu/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-0', 'Malé is the capital of Maldives.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-1', 'A sultanate since the 12th century, the Maldives became a British protectorate in 1887 and a republic in 1968, three years after independence.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-10', 'In 2018, YAMEEN lost his reelection bid to parliamentarian Ibrahim Mohamed SOLIH.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-11', 'YAMEEN was arrested and jailed in 2022 on corruption charges.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-12', 'Maldives'' fourth democratic election was held in September 2023.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-13', 'Mohamed MUIZZU, campaigned on a platform of Maldivian sovereignty, vowing to remove Indian military personnel from the country.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-14', 'MUIZZU represents a joint Progressive Pary of Maldives and People''s National Congress (PPM/PNC) coalition.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-2', 'President Maumoon Abdul GAYOOM dominated Maldives'' political scene for 30 years, elected to six successive terms by single-party referendums.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-3', 'After political demonstrations in the capital Male in 2003, GAYOOM and his government pledged to embark upon a process of liberalization and democratic reforms, including a more representative political system and expanded political freedoms.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-4', 'In 2008, a constituent assembly -- termed the "Special Majlis" -- finalized a new constitution ratified by GAYOOM.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-5', 'The first-ever presidential elections under a multi-candidate, multi-party system were held later that year.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-6', 'GAYOOM was defeated in a runoff by Mohamed NASHEED, a political activist whom the regime had jailed several years earlier.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-7', 'In 2012, after several weeks of street protests in response to a top judge''s arrest, NASHEED resigned the presidency and handed over power to Vice President Mohammed WAHEED Hassan Maniku.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-8', 'A government-appointed Commission of National Inquiry concluded that there was no evidence of a coup, but NASHEED contended that police and military personnel forced him to resign.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mv-9', 'NASHEED, WAHEED, and Abdulla YAMEEN Abdul Gayoom ran in the 2013 elections with YAMEEN ultimately winning the presidency after three rounds of voting.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALDIVES"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mv/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mv/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mx-0', 'Mexico City (Ciudad de Mexico) is the capital of Mexico.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MEXICO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mx/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mx/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mx-1', 'Mexico was the site of several advanced Amerindian civilizations -- including the Olmec, Toltec, Teotihuacan, Zapotec, Maya, and Aztec -- until Spain conquered and colonized the area in the early 16th century.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MEXICO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mx/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mx/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mx-10', 'Since 2007, Mexico''s powerful transnational criminal organizations have engaged in a struggle to control criminal markets, resulting in tens of thousands of drug-related homicides and forced disappearances.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MEXICO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mx/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mx/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mx-2', 'Administered as the Viceroyalty of New Spain for three centuries, it achieved independence early in the 19th century.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MEXICO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mx/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mx/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mx-3', 'Elections held in 2000 marked the first time since Mexican Revolution in 1910 that an opposition candidate -- Vicente FOX of the National Action Party (PAN) -- defeated the party in government, the Institutional Revolutionary Party (PRI).', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MEXICO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mx/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mx/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mx-4', 'He was succeeded in 2006 by another PAN candidate Felipe CALDERON, but Enrique PEÑA NIETO regained the presidency for the PRI in 2012.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MEXICO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mx/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mx/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mx-5', 'Left-leaning anti-establishment politician and former mayor of Mexico City (2000-05) Andrés Manuel LÓPEZ OBRADOR, from the National Regeneration Movement (MORENA), became president in 2018.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MEXICO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mx/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mx/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mx-6', 'The US-Mexico-Canada Agreement (USMCA, or T-MEC by its Spanish acronym) entered into force in 2020 and replaced its predecessor, the North American Free Trade Agreement (NAFTA).', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MEXICO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mx/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mx/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mx-7', 'Mexico amended its constitution in 2019 to facilitate the implementation of the labor components of USMCA.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MEXICO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mx/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mx/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mx-8', 'Mexico is currently the US''s second-largest goods trading partner, after Canada.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MEXICO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mx/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mx/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mx-9', 'Ongoing economic and social concerns include low real wages, high underemployment, inequitable income distribution, and few advancement opportunities, particularly for the largely indigenous population in the impoverished southern states.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MEXICO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mx/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mx/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-my-0', 'Kuala Lumpur is the capital of Malaysia.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALAYSIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/my/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/my/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-my-1', 'Malaysia’s location has long made it an important cultural, economic, historical, social, and trade link between the islands of Southeast Asia and the mainland.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALAYSIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/my/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/my/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-my-10', 'From 2018-2022, Malaysia underwent considerable political upheaval, with a succession of coalition governments holding power.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALAYSIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/my/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/my/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-my-11', 'Following legislative elections in 2022, ANWAR Ibrahim was appointed prime minister after more than 20 years in opposition.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALAYSIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/my/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/my/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-my-12', 'His political coalition, Pakatan Harapan (PH), joined its longtime UNMO rival to form a government, but the two groups have remained deeply divided on many issues.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALAYSIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/my/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/my/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-my-2', 'Through the Strait of Malacca, which separates the Malay Peninsula from the archipelago, flowed maritime trade and with it influences from China, India, the Middle East, and the east coast of Africa.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALAYSIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/my/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/my/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-my-3', 'The Portuguese in the 16th century and the Dutch in the 17th century were the first European colonial powers to establish themselves on the Malay Peninsula and in Southeast Asia.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALAYSIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/my/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/my/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-my-4', 'However, it was the British who ultimately secured hegemony across the territory and during the late 18th and 19th centuries established colonies and protectorates in the area that is now Malaysia.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALAYSIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/my/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/my/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-my-5', 'In 1948, the British-ruled territories on the Malay Peninsula (except Singapore) formed the Federation of Malaya, which became independent in 1957.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALAYSIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/my/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/my/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-my-6', 'Malaysia was formed in 1963 when the former British colonies of Singapore, as well as Sabah and Sarawak on the northern coast of Borneo, joined the Federation.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALAYSIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/my/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/my/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-my-7', 'A communist insurgency, confrontations with Indonesia, Philippine claims to Sabah, and Singapore''s expulsion in 1965 marred the first several years of the country''s independence.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALAYSIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/my/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/my/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-my-8', 'During the 22-year term of Prime Minister MAHATHIR Mohamad (1981-2003), Malaysia was successful in diversifying its economy from dependence on exports of raw materials to the development of manufacturing, services, and tourism.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALAYSIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/my/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/my/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-my-9', 'Former Prime Minister MAHATHIR and a newly formed coalition of opposition parties defeated Prime Minister Mohamed NAJIB bin Abdul Razak''s United Malays National Organization (UMNO) in 2018, ending over 60 years of uninterrupted UMNO rule.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MALAYSIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/my/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/my/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mz-0', 'Maputo is the capital of Mozambique.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MOZAMBIQUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mz-1', 'In the first half of the second millennium A.D., northern Mozambican port towns were frequented by traders from Somalia, Ethiopia, Egypt, Arabia, Persia, and India.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MOZAMBIQUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mz-10', 'In 2021, Rwanda and the Southern African Development Community deployed forces to support Mozambique’s efforts to counter the extremist group.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MOZAMBIQUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mz-2', 'The Portuguese were able to wrest much of the coastal trade from Arab Muslims in the centuries after 1500, and they set up their own colonies.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MOZAMBIQUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mz-3', 'Large-scale emigration, economic dependence on South Africa, a severe drought, and a prolonged civil war hindered the country''s development until the mid-1990s.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MOZAMBIQUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mz-4', 'The ruling Front for the Liberation of Mozambique (FRELIMO) party formally abandoned Marxism in 1989, and a new constitution the following year provided for multiparty elections and a free-market economy.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MOZAMBIQUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mz-5', 'A UN-negotiated peace agreement between FRELIMO and rebel Mozambique National Resistance (RENAMO) forces ended the fighting in 1992.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MOZAMBIQUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mz-6', 'In 2004, Mozambique underwent a delicate transition as Joaquim CHISSANO stepped down after 18 years in office.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MOZAMBIQUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mz-7', 'His elected successor, Armando GUEBUZA, served two terms and then passed executive power to Filipe NYUSI in 2015.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MOZAMBIQUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mz-8', 'RENAMO’s residual armed forces intermittently engaged in a low-level insurgency after 2012, but a 2016 cease-fire eventually led to the two sides signing a comprehensive peace deal in 2019.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MOZAMBIQUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-mz-9', 'Since 2017, violent extremists -- who an official ISIS media outlet recognized as ISIS''s network in Mozambique for the first time in 2019 -- have been conducting attacks against civilians and security services in the northern province of Cabo Delgado.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.MOZAMBIQUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/mz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/mz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-0', 'Noumea is the capital of New Caledonia.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-1', 'The Lapita were skilled navigators, and evidence of their pottery around the Pacific has served as a guide for understanding human expansion in the region.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-10', 'During World War II, New Caledonia became an important base for Allied troops, and the US moved its South Pacific headquarters to the island in 1942.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-11', 'Following the war, France made New Caledonia an overseas territory and granted French citizenship to all inhabitants in 1953, thereby permitting the Kanaks to move off the reservations.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-12', 'The Kanak nationalist movement began in the 1950s, but most voters chose to remain a territory in an independence referendum in 1958.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-13', 'The European population of New Caledonia boomed in the 1970s with a renewed focus on nickel mining, reigniting Kanak nationalism.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-14', 'Key Kanak leaders were assassinated in the early 1980s, leading to escalating violence and dozens of fatalities.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-15', 'The Matignon Accords of 1988 provided for a 10-year transition period.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-16', 'The Noumea Accord of 1998 transferred increasing governing responsibility from France to New Caledonia over a 20-year period and provided for three independence referenda.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-17', 'In the first held in 2018, voters rejected independence by 57% to 43%; in the second held in 2020, voters rejected independence 53% to 47%.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-18', 'In the third referendum held in 2021, voters rejected independence 96% to 4%; however, a boycott by key Kanak groups spurred challenges about the legitimacy of the vote.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-19', 'Pro-independence parties subsequently won a majority in the New Caledonian Government for the first time.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-2', 'Successive waves of migrants from other islands in Melanesia intermarried with the Lapita, giving rise to the Kanak ethnic group considered indigenous to New Caledonia.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-20', 'France and New Caledonia officials remain in talks about the status of the territory.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-3', 'British explorer James COOK was the first European to visit New Caledonia in 1774, giving it the Latin name for Scotland.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-4', 'In 1853, France annexed New Caledonia to preclude any British attempt to claim the island.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-5', 'France declared it a penal colony in 1864 and sent more than 20,000 prisoners to New Caledonia in the ensuing three decades.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-6', 'Nickel was discovered in 1864, and French prisoners were directed to mine it.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-7', 'France brought in indentured servants and enslaved labor from elsewhere in Southeast Asia to work the mines, blocking Kanaks from accessing the most profitable part of the local economy.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-8', 'In 1878, High Chief ATAI led a rebellion against French rule.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nc-9', 'The Kanaks were relegated to reservations, leading to periodic smaller uprisings and culminating in a large revolt in 1917 that colonial authorities brutally suppressed.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NEWCALEDONIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nc/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nc/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ne-0', 'Alofi is the capital of Niue.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ne/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ne/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ne-1', 'With only one reliable source of fresh water, conflict was high on the island.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ne/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ne/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ne-2', 'Samoan and Tongan customs heavily influenced Niuean culture, including the formation of an island-wide elected kingship system in the early 1700s.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ne/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ne/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ne-3', 'In 1774, British explorer James COOK landed on the island and named it Savage Island because of the Niueans'' hostility.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ne/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ne/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ne-4', 'Missionaries arrived in 1830 but were also largely unsuccessful at staying on the island until 1846, when a Niuean trained as a Samoan missionary returned to the island and provided a space from which the missionaries could work.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ne/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ne/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ne-5', 'In addition to converting the population, the missionaries worked to stop the violent conflicts and helped establish the first parliament in 1849.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ne/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ne/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ne-6', 'The following year, Niue was annexed to New Zealand and included as part of the Cook Islands.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ne/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ne/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ne-7', 'Niue’s remoteness and cultural and linguistic differences with the Cook Islands led New Zealand to separate Niue into its own administration in 1904.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ne/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ne/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ne-8', 'The island became internally self-governing in 1974; it is an independent member of international organizations but is in free association with New Zealand, which is responsible for defense and foreign affairs.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ne/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ne/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ne-9', 'In September 2023, the US recognized Niue as a sovereign and independent state.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIUE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ne/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ne/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nf-0', 'Kingston is the capital of Norfolk Island.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORFOLKISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nf-1', 'Polynesians lived on Norfolk Island between 1200 and 1500, but the remote island was uninhabited by the time British explorer James COOK landed on the island in 1774.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORFOLKISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nf-10', 'Most services are provided by a mix of the Australian Capital Territory and the states of New South Wales and Queensland.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORFOLKISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nf-11', 'These moves were unpopular on Norfolk Island, which has sought to have its self-government restored and as of 2024, the Australian Government was working with Norfolk Island to establish a new local governing body.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORFOLKISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nf-2', 'Two British attempts at establishing the island as a penal colony (1788-1814 and 1825-55) were ultimately abandoned.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORFOLKISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nf-3', 'In 1856, almost 200 Pitcairn Islanders -- descendants of the Bounty mutineers and their Tahitian companions -- were relocated to Norfolk Island because of overcrowding on the Pitcairn Islands.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORFOLKISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nf-4', 'Some returned to the Pitcairn Islands over the next few years, but most settled permanently on Norfolk Island and recreated their previous land tenure and governance structures.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORFOLKISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nf-5', 'Norfolk Island retained a great degree of local control until 1897, when it became a dependency of New South Wales.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORFOLKISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nf-6', 'During World War II, Norfolk Island was an airbase and an important refueling stop in the South Pacific.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORFOLKISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nf-7', 'In 1976, an Australian judge recommended Norfolk Island be incorporated fully into Australia, which Norfolk Islanders rejected.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORFOLKISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nf-8', 'After an appeal to the UN, Australia granted limited self-government to Norfolk Island in 1979.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORFOLKISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nf-9', 'With growing financial troubles during the 2000s, Australia abolished the Norfolk Island Legislative Assembly in 2015, reduced Norfolk Island’s autonomy in 2016, and suspended the local council in 2020.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NORFOLKISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-0', 'Niamey is the capital of Niger.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-1', 'Nomadic peoples from the Saharan north and agriculturalists from the south settled present-day Niger.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-10', 'TANDJA was reelected in 2004 and spearheaded a 2009 constitutional amendment allowing him to extend his presidential term.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-11', 'In 2010, military officers led another coup that deposed TANDJA.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-12', 'ISSOUFOU Mahamadou was elected in 2011 and reelected in 2016.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-13', 'In 2021, BAZOUM Mohamed won the presidential election, marking Niger’s first transition from one democratically elected president to another.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-14', 'Nonetheless, a military junta led by General Abdourahamane TIANI once again seized power in July 2023, detaining President BAZOUM and announcing the creation of a National Council for the Safeguarding of the Homeland (CNSP).', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-15', 'Niger is one of the poorest countries in the world with minimal government services and insufficient funds to develop its resource base.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-16', 'It is ranked fourth to last in the world on the UN Development Program''s Human Development Index of 2023/2024.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-17', 'The largely agrarian and subsistence-based economy is frequently disrupted by extended droughts common to the Sahel region of Africa.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-18', 'The Nigerien Government continues its attempts to diversify the economy through increased oil production and mining projects.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-19', 'In addition, Niger is facing increased security concerns on its borders from various external threats including insecurity in Libya, spillover from the conflict and terrorism in Mali, and violent extremism in northeastern Nigeria.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-2', 'The Taureg kingdom of Takedda was one of the largest kingdoms in the north and played a prominent role in regional trade in the 14th century.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-3', 'In the south, the primary ethnic groups were the Songhai-Zarma in the west, the Hausa in the center, and the Kanuri in the east.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-4', 'When European colonizers arrived in the 19th century, the region was an assemblage of disparate local kingdoms.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-5', 'In the late 19th century, the British and French agreed to partition the middle regions of the Niger River, and France began its conquest of what would become the colony of Niger.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-6', 'France experienced determined local resistance -- particularly during the Tuareg uprising (1916-1917) -- but established a colonial administration in 1922.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-7', 'After achieving independence from France in 1960, Niger experienced single-party or military rule until 1991, when political pressure forced General Ali SAIBOU to allow multiparty elections.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-8', 'Political infighting and democratic backsliding led to coups in 1996 and 1999.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ng-9', 'In 1999, military officers restored democratic rule and held elections that brought Mamadou TANDJA to power.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGER"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ng/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ng/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-0', 'Port-Vila (on Efate) is the capital of Vanuatu.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-1', 'By around 1000, localized chieftain systems began to develop on the islands.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-10', 'During the war, the US stationed up to 50,000 soldiers in Vanuatu.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-11', 'In 1945, they withdrew and sold their equipment, leading to the rise of political and religious movements known as "cargo cults," such as the John Frum movement.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-12', 'The UK-France condominium was reestablished after World War II.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-13', 'The UK was interested in moving the condominium toward independence in the 1960s, but France was hesitant.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-14', 'Political parties agitating for independence began to form, largely divided along linguistic lines.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-15', 'France eventually relented, and elections were held in 1974, with independence granted to the newly named Vanuatu in 1980 under English-speaking Prime Minister Walter LINI.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-16', 'The Nagriamel Movement, with support from French-speaking landowners, then declared the island of Espiritu Santo independent from Vanuatu, but the short-lived state was dissolved 12 weeks later.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-17', 'Linguistic divisions have lessened over time, but highly fractious political parties have led to weak coalition governments that require support from both Anglophone and Francophone parties.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-18', 'Since 2008, prime ministers have been ousted more than a dozen times through no-confidence motions or temporary procedural issues.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-2', 'Around 1600, Melanesian Chief ROI MATA united some of the islands of modern-day Vanuatu under his rule.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-3', 'In 1606, a Portuguese explorer was the first European to see Vanuatu''s Banks Islands and Espiritu Santo, setting up a short-lived settlement on the latter.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-4', 'The next European explorers arrived in the 1760s, and the islands -- then known as the New Hebrides -- were frequented by whalers in the 1800s.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-5', 'European interest in harvesting the islands’ sandalwood trees caused conflict with the inhabitants.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-6', 'In the 1860s, European planters in Australia, Fiji, New Caledonia, and Samoa needed labor and kidnapped almost half the adult males on the islands to work as indentured servants.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-7', 'With growing and overlapping interests in the islands, France and the UK agreed that the New Hebrides would be neutral in 1878 and established a joint naval commission in 1887.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-8', 'In 1906, the two countries created the UK-France condominium to jointly administer the islands, with separate laws, police forces, currencies, and education and health systems.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nh-9', 'The condominium arrangement was dysfunctional, and the UK used France’s initial defeat in World War II to assert greater control over the islands.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.VANUATU"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nh/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nh/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-0', 'Abuja is the capital of Nigeria.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-1', 'In ancient and pre-colonial times, the area of present-day Nigeria was occupied by a variety of ethnic groups with different languages and traditions.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-10', 'This generation of officers, including Olusegun OBASANJO, Ibrahim BABANGIDA, and Muhammadu BUHARI, who would all later serve as president, continue to exert significant influence in Nigeria to the present day.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-11', 'Military rule predominated until the first durable transition to civilian government and adoption of a new constitution in 1999.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-12', 'The elections of 2007 marked the first civilian-to-civilian transfer of power in the country''s history.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-13', 'National and state elections in 2011 and 2015 were generally regarded as credible.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-14', 'The 2015 election was also heralded for the fact that the then-umbrella opposition party, the All Progressives Congress, defeated the long-ruling (since 1999) People''s Democratic Party and assumed the presidency, marking the first peaceful transfer of power from one party to another.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-15', 'Presidential and legislative elections in 2019 and 2023 were deemed broadly free and fair despite voting irregularities, intimidation, and violence.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-16', 'The government of Africa''s most populous nation continues to face the daunting task of institutionalizing democracy and reforming a petroleum-based economy whose revenues have been squandered through decades of corruption and mismanagement.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-17', 'In addition, Nigeria faces increasing violence from Islamic terrorism, largely in the northeast, large scale criminal banditry, secessionist violence in the southeast, and competition over land and resources nationwide.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-2', 'These included large Islamic kingdoms such as Borno, Kano, and the Sokoto Caliphate dominating the north, the Benin and Oyo Empires that controlled much of modern western Nigeria, and more decentralized political entities and city states in the south and southeast.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-3', 'In 1914, the British amalgamated their separately administered northern and southern territories into a Colony and Protectorate of Nigeria.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-4', 'Nigeria achieved independence from Britain in 1960 and transitioned to a federal republic with three constituent states in 1963 under President Nnamdi AZIKIWE.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-5', 'This structure served to enflame regional and ethnic tension, contributing to a bloody coup led by predominately southeastern military officers in 1966 and a countercoup later that year masterminded by northern officers.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-6', 'In the aftermath of this tension, the governor of Nigeria’s Eastern Region, centered on the southeast, declared the region independent as the Republic of Biafra.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-7', 'The ensuring civil war (1967-1970), resulted in more than a million deaths, many from starvation.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-8', 'While the war forged a stronger Nigerian state and national identity, it contributed to long-lasting mistrust of the southeast’s predominantly Igbo population.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ni-9', 'Wartime military leader Yakubu GOWON ruled until a bloodless coup by frustrated junior officers in 1975.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NIGERIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ni/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ni/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nl-0', 'Amsterdam is the capital of Netherlands.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NETHERLANDS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nl/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nl/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nl-1', 'The Dutch United Provinces declared their independence from Spain in 1581; during the 17th century, they became a leading seafaring and commercial power, with settlements and colonies around the world.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NETHERLANDS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nl/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nl/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nl-2', 'After 18 years of French domination, the Netherlands regained its independence in 1813.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NETHERLANDS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nl/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nl/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nl-3', 'The Netherlands remained neutral in World War I but suffered German invasion and occupation in World War II.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NETHERLANDS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nl/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nl/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nl-4', 'A modern, industrialized nation, the Netherlands is also a large exporter of agricultural products.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NETHERLANDS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nl/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nl/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nl-5', 'The country was a founding member of NATO and the EEC (now the EU) and participated in the introduction of the euro in 1999.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NETHERLANDS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nl/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nl/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nl-6', 'In 2010, the former Netherlands Antilles was dissolved and the three smallest islands -- Bonaire, Sint Eustatius, and Saba -- became special municipalities in the Netherlands administrative structure.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NETHERLANDS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nl/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nl/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nl-7', 'The larger islands of Sint Maarten and Curacao joined the Netherlands and Aruba as constituent countries forming the Kingdom of the Netherlands.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NETHERLANDS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nl/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nl/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nl-8', 'In 2018, the Sint Eustatius island council (governing body) was dissolved and replaced by a government commissioner to restore the integrity of public administration.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NETHERLANDS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nl/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nl/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nl-9', 'According to the Dutch Government, the intervention will be as "short as possible and as long as needed.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.NETHERLANDS"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nl/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nl/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nn-0', 'Philipsburg is the capital of Sint Maarten.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SINTMAARTEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nn-1', 'Christopher COLUMBUS claimed Saint Martin for Spain in 1493, naming it after the feast day of St.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SINTMAARTEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nn-10', 'In 2017, Hurricane Irma hit Saint Martin/Sint Maarten, causing extensive damage to roads, communications, electrical power, and housing; the UN estimated that 90% of the buildings were damaged or destroyed.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SINTMAARTEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nn-2', 'Martin of Tours, but it was the Dutch who occupied the island in 1631 to exploit its salt deposits.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SINTMAARTEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nn-3', 'The Spanish retook Saint Martin in 1633, but the Dutch continued to assert their claims.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SINTMAARTEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nn-4', 'The Spanish finally relinquished the island to the French and Dutch, who divided it between themselves in 1648.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SINTMAARTEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nn-5', 'The border frequently fluctuated over the next 200 years because of friction between the two countries, with the Dutch eventually holding the smaller portion of the island (about 39%) and adopting the Dutch spelling of the island''s name for their territory.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SINTMAARTEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nn-6', 'The establishment of cotton, tobacco, and sugar plantations dramatically expanded African slavery on the island in the 18th and 19th centuries; the practice was not abolished in the Dutch half until 1863.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SINTMAARTEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nn-7', 'The island''s economy declined until 1939 when it became a free port; the tourism industry was dramatically expanded beginning in the 1950s.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SINTMAARTEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nn/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-nn-8', 'In 1954, Sint Maarten and several other Dutch Caribbean possessions became part of the Kingdom of the Netherlands as the Netherlands Antilles.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SINTMAARTEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/nn/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/nn/', 'factbook.json') on conflict (anchor_id) do nothing;
