insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-td-0', 'Port of Spain is the capital of Trinidad and Tobago.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.TRINIDADANDTOBAGO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/td/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/td/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-td-1', 'First colonized by the Spanish, Trinidad and Tobago came under British control in the early 19th century.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.TRINIDADANDTOBAGO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/td/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/td/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-td-2', 'The emancipation of enslaved people in 1834 disrupted the twin islands'' sugar industry.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.TRINIDADANDTOBAGO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/td/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/td/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-td-3', 'Contract workers arriving from India between 1845 and 1917 augmented the labor force, which boosted sugar production as well as the cocoa industry.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.TRINIDADANDTOBAGO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/td/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/td/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-td-4', 'The discovery of oil on Trinidad in 1910 added another important export that remains the country''s dominant industry.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.TRINIDADANDTOBAGO"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/td/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/td/', 'factbook.json') on conflict (anchor_id) do nothing;
