insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-we-11', 'In recent years, Fatah and HAMAS have made several attempts at reconciliation, but the factions have been unable to implement agreements.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTBANK"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/we/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/we/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-we-2', 'In the early 16th century, it was incorporated into the Ottoman Empire.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTBANK"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/we/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/we/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-we-3', 'The West Bank fell to British forces during World War I, becoming part of the British Mandate of Palestine.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTBANK"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/we/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/we/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-we-4', 'After the 1948 Arab-Israeli War, Transjordan (later renamed Jordan) captured the West Bank and annexed it in 1950; Israel then captured it in the Six-Day War in 1967.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTBANK"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/we/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/we/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-we-5', 'Under the Oslo Accords -- a series of agreements that were signed between 1993 and 1999 -- Israel transferred to the newly created Palestinian Authority (PA) security and civilian responsibility for the many Palestinian-populated areas of the West Bank, as well as the Gaza Strip.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTBANK"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/we/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/we/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-we-6', 'In 2000, a violent intifada , or uprising, began across the Palestinian territories, and in 2001, negotiations for a permanent agreement between the PLO and Israel on final status issues stalled.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTBANK"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/we/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/we/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-we-7', 'Subsequent attempts to re-start direct negotiations have not resulted in progress toward determining final status of the area.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTBANK"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/we/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/we/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-we-8', 'The PA last held national elections in 2006, when the Islamic Resistance Movement (HAMAS) won a majority of seats in the Palestinian Legislative Council (PLC).', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTBANK"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/we/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/we/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-we-9', 'Fatah, the dominant Palestinian political faction in the West Bank, and HAMAS failed to maintain a unity government, leading to violent clashes between their respective supporters and to HAMAS''s violent seizure of all PA military and governmental institutions in the Gaza Strip in 2007.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTBANK"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/we/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/we/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-0', 'Mata-Utu (on Ile Uvea) is the capital of Wallis and Futuna.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-1', 'Around 800 B.C., the first settlers arrived on the islands of Wallis and Futuna, which are a natural midpoint between Fiji and Samoa.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-10', 'Wallis and Futuna was the only French colony to side with the Vichy regime during World War II, until the arrival of Free French and US troops in 1942.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-11', 'In 1959, inhabitants of the islands voted to separate from New Caledonia, becoming a French overseas territory in 1961.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-12', 'Despite the split, a significant Wallisian and Futunan community still lives in New Caledonia.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-13', 'In 2003, Wallis and Futuna became a French overseas collectivity.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-14', 'The islands joined the Pacific Islands Forum as an associate member in 2018, two years after France’s other Pacific territories became full members of the organization.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-2', 'Tongans attempted to settle Futuna but were repeatedly rebuffed.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-3', 'Samoans settled Futuna in the 1600s, and a slightly less centralized chiefdom system formed.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-4', 'Dutch explorers were the first Europeans to see the islands in 1616, followed intermittently by other Europeans, including British explorer Samuel WALLIS in 1767.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-5', 'French Catholic missionaries were the first Europeans to permanently settle Wallis and Futuna in 1837, and they converted most of the population of both islands by 1846.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-6', 'The missionaries and newly converted King LAVELUA of Uvea on Wallis asked France for a protectorate in 1842 following a local rebellion.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-7', 'France agreed, although the protectorate status would not be ratified until 1887.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-8', 'In 1888, King MUSULAMU of Alo and King TAMOLE of Sigave, both on Futuna, signed a treaty establishing a French protectorate; the Wallis and Futuna protectorate was integrated into the territory of New Caledonia the same year.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wf-9', 'France renegotiated the terms of the protectorate with the territory’s three kings in 1910, expanding French authority.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WALLISANDFUTUNA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wf/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wf/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wi-0', 'Western Sahara is a non-self-governing territory on the northwest coast of Africa bordered by Morocco, Mauritania, and Algeria.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTERNSAHARA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wi-1', 'After Spain withdrew from its former colony of Spanish Sahara in 1976, Morocco annexed the northern two-thirds of Western Sahara and claimed the rest of the territory in 1979, following Mauritania''s withdrawal.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTERNSAHARA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wi-2', 'A guerrilla war with the Polisario Front contesting Morocco''s sovereignty ended in a 1991 cease-fire and the establishment of a UN peacekeeping operation.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTERNSAHARA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wi-3', 'As part of this effort, the UN sought to offer a choice to the peoples of Western Sahara between independence (favored by the Polisario Front) or integration into Morocco.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTERNSAHARA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wi-4', 'A proposed referendum on the question of independence never took place due to lack of agreement on voter eligibility.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTERNSAHARA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wi-5', 'The approximately 1,600 km- (almost 1,000 mi-) long defensive sand berm, built by the Moroccans from 1980 to 1987 and running the length of the territory, continues to separate the opposing forces, with Morocco controlling the roughly three-quarters of the territory west of the berm.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTERNSAHARA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wi-6', 'There are periodic ethnic tensions between the native Sahrawi population and Moroccan immigrants.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTERNSAHARA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wi-7', 'Morocco maintains a heavy security presence in the territory.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTERNSAHARA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wi-8', 'The UN revived direct talks about the territory between Morocco, the Polisario Front, Algeria, and Mauritania in December 2018.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WESTERNSAHARA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wq-0', 'Early Micronesian and Polynesian settlers probably visited Wake Island, and oral legends tell of periodic voyages to the islands by people from the Marshall Islands.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WAKEISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wq/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wq/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wq-1', 'Wake Island was uninhabited when Spanish explorer Alvaro de Mendana de NEYRA became the first European to see it in 1568 and still had no inhabitants when English captain Samuel WAKE sailed by it in 1796.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WAKEISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wq/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wq/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wq-10', 'In 2009, Wake Island was included in the Pacific Remote Islands Marine National Monument.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WAKEISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wq/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wq/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wq-2', 'The United States Exploring Expedition visited the island in 1841, and the US annexed it in 1899 to use as a cable and refueling station for its newly acquired Pacific territories of Hawaii, the Philippines, and Guam.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WAKEISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wq/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wq/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wq-3', 'In the 1930s, Pan American Airways built facilities on Wake Island so that it could be used as a stopover for flights from the US to China.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WAKEISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wq/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wq/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wq-4', 'In 1941, the US began to install military assets on Wake Island, and Japan then captured the island and held it until the end of World War II.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WAKEISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wq/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wq/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wq-5', 'In 1946, commercial airlines resumed using Wake Island as a refueling stop.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WAKEISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wq/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wq/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wq-6', 'In 1973, the Marshall Islands claimed Wake Island, based on the oral legends, although the US has not recognized these claims.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WAKEISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wq/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wq/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wq-7', 'In 1974, the US military took exclusive control of the island’s airstrip and restricted visitors.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WAKEISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wq/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wq/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wq-8', 'In 1978, Bikini Islanders from the Marshall Islands, who were evacuated in the 1950s and 1960s because of US nuclear tests, considered rehoming on Wake Island, but the US military rejected that plan.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WAKEISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wq/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wq/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wq-9', 'Since the 1970s, the island has been important for missile defense testing.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.WAKEISLAND"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wq/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wq/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-0', 'Apia is the capital of Samoa.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-1', 'The first Austronesian settlers arrived in Samoa around 1000 B.C., and early Samoans traded and intermarried with Fijian and Tongan nobility.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-10', 'The UK abandoned claims in Samoa and received former German territory in the Solomon Islands.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-11', 'New Zealand occupied Samoa during World War I but was accused of negligence and opposed by many Samoans, particularly an organized political movement called the Mau (“Strongly Held View”) that advocated for independence.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-12', 'During the 1918-1919 influenza pandemic, about 20% of the population died.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-13', 'In 1929, New Zealand police shot into a crowd of peaceful Mau protestors, killing 11, in an event known as Black Sunday.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-14', 'In 1962, Samoa became the first Polynesian nation to reestablish its independence as Western Samoa but dropped the “Western” from its name in 1997.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-15', 'The Human Rights Protection Party dominated politics from 1982 until Prime Minister FIAME Naomi Mata''afa''s Fa''atuatua i le Atua Samoa ua Tasi (FAST) party gained a majority in elections in 2021.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-2', 'The fa’amatai system of titles and nobility developed, which dominates Samoan politics to this day; all but two seats in the legislature are reserved for matai, or heads of families.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-3', 'A Dutch explorer was the first European to spot the islands in 1722.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-4', 'Christian missionaries arrived in the 1830s and were followed by an influx of American and European settlers and influence.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-5', 'By the 1880s, Germany, the UK, and the US had trading posts and claimed parts of the kingdom.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-6', 'In 1886, an eight-year civil war broke out, with rival matai factions fighting over royal succession and the three foreign powers providing support to the factions.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-7', 'Germany, the UK, and the US all sent warships to Apia in 1889 and came close to conflict, but a cyclone damaged or destroyed the ships of all three navies.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-8', 'At the end of the civil war in 1894, Malietoa LAUPEPA was installed as king, but upon his death in 1898, a second civil war over succession broke out.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ws-9', 'When the war ended in 1899, the Western powers abolished the monarchy, giving the western Samoan islands to Germany and the eastern Samoan islands to the US.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.SAMOA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ws/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ws/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wz-0', 'Mbabane (administrative capital); Lobamba (royal and legislative capital) is the capital of Eswatini.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ESWATINI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wz-1', 'A Swazi kingdom was founded in the mid-18th century and ruled by a series of kings, including MSWATI II, a 19th century ruler whose name was adopted for the country and its predominant ethnic group.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ESWATINI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wz-10', 'Eswatini is the only country in Africa that recognizes Taiwan.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ESWATINI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wz-2', 'European countries defined the kingdom’s modern borders during the late-19th century, and Swaziland (as it became known) was administered as a UK high commission territory from 1903 until its independence in 1968.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ESWATINI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wz-3', 'A new constitution that came into effect in 2005 included provisions for a more independent parliament and judiciary, but the legal status of political parties remains unclear, and the kingdom is still considered an absolute monarchy.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ESWATINI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wz-4', 'King MSWATI III renamed the country from Swaziland to Eswatini in 2018 to reflect the name most commonly used by its citizens.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ESWATINI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wz-5', 'In 2021, MSWATI III used security forces to suppress prodemocracy protests.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ESWATINI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wz-6', 'A national dialogue and reconciliation process agreed to in the wake of violence has not materialized.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ESWATINI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wz-7', 'In November 2023, King MSWATI III appointed a new prime minister following peaceful national elections.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ESWATINI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wz-8', 'Despite its classification as a lower-middle income country, Eswatini suffers from severe poverty, corruption, and high unemployment.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ESWATINI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-wz-9', 'Eswatini has the world''s highest HIV/AIDS prevalence rate, although recent years have shown marked declines in new infections.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ESWATINI"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/wz/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/wz/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-0', 'Sanaa is the capital of Yemen.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-1', 'The Kingdom of Yemen (colloquially known as North Yemen) became independent from the Ottoman Empire in 1918 and in 1962 became the Yemen Arab Republic.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-10', 'The Gulf Cooperation Council (GCC) mediated the crisis with the GCC Initiative, an agreement in which the president would step down in exchange for immunity from prosecution.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-11', 'SALIH eventually agreed to step down and transfer some powers to Vice President Abd Rabuh Mansur HADI.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-12', 'After HADI''s uncontested election victory in 2012, SALIH formally transferred all presidential powers.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-13', 'In accordance with the GCC Initiative, Yemen launched a National Dialogue Conference (NDC) in 2013 to discuss key constitutional, political, and social issues.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-14', 'HADI concluded the NDC in 2014 and planned to proceed with constitutional drafting, a constitutional referendum, and national elections.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-15', 'The Houthis, perceiving their grievances were not addressed in the NDC, joined forces with SALIH and expanded their influence in northwestern Yemen, which culminated in a major offensive against military units and rival tribes and enabled their forces to overrun the capital, Sana''a, in 2014.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-16', 'In 2015, the Houthis surrounded key government facilities, prompting HADI and the cabinet to resign.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-17', 'HADI fled first to Aden -- where he rescinded his resignation -- and then to Oman before moving to Saudi Arabia and asking the GCC to intervene militarily in Yemen.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-18', 'Saudi Arabia assembled a coalition of Arab militaries and began airstrikes, and ground fighting continued through 2016.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-19', 'In 2016, the UN initiated peace talks that ended without agreement.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-2', 'The British, who had set up a protectorate area around the southern port of Aden in the 19th century, withdrew in 1967 from what became the People''s Republic of Southern Yemen (colloquially known as South Yemen).', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-20', 'Rising tensions between the Houthis and SALIH culminated in Houthi forces killing SALIH.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-21', 'In 2018, the Houthis and the Yemeni Government participated in UN-brokered peace talks, agreeing to a limited cease-fire and the establishment of a UN mission.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-22', 'In 2019, Yemen’s parliament convened for the first time since the conflict broke out in 2014.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-23', 'Violence then erupted between HADI''s government and the pro-secessionist Southern Transitional Council (STC) in southern Yemen.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-24', 'HADI''s government and the STC signed a power-sharing agreement to end the fighting, and in 2020, the signatories formed a new cabinet.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-25', 'In 2020 and 2021, fighting continued as the Houthis gained territory and also conducted regular UAV and missile attacks against targets in Saudi Arabia.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-26', 'In 2022, the UN brokered a temporary truce between the Houthis and the Saudi-led coalition.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-27', 'HADI and his vice-president resigned and were replaced by an eight-person Presidential Leadership Council.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-28', 'Although the truce formally expired in 2022, the parties nonetheless refrained from large-scale conflict through the end of 2023.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-29', 'Saudi Arabia, after the truce expired, continued to negotiate with the Yemeni Government and Houthis on a roadmap agreement that would include a permanent ceasefire and a peace process under UN auspices.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-3', 'Three years later, the southern government adopted a Marxist orientation and changed the country''s name to the People''s Democratic Republic of Yemen.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-4', 'The exodus of hundreds of thousands of Yemenis from the south to the north contributed to two decades of hostility between the states, which were formally unified as the Republic of Yemen in 1990.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-5', 'A southern secessionist movement and brief civil war in 1994 was quickly subdued.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-6', 'In 2000, Saudi Arabia and Yemen agreed to delineate their border.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-7', 'Fighting in the northwest between the government and the Houthis, a Zaydi Shia Muslim minority, continued intermittently from 2004 to 2010, and then again from 2014 to the present.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-8', 'Public rallies in Sana''a against then President Ali Abdallah SALIH -- inspired by similar Arab Spring demonstrations in Tunisia and Egypt -- slowly gained momentum in 2011, fueled by complaints over high unemployment, poor economic conditions, and corruption.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-ym-9', 'Some protests resulted in violence, and the demonstrations spread to other major cities.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.YEMEN"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/ym/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/ym/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-0', 'Lusaka is the capital of Zambia.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-1', 'The Mutapa Empire developed after the fall of Great Zimbabwe to the south in the 14th century and ruled the region, including large parts of Zambia, from the 14th to 17th century.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-10', 'Elections in 1991 brought an end to one-party rule and propelled the Movement for Multiparty Democracy (MMD) into power.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-11', 'The subsequent vote in 1996, however, saw increasing harassment of opposition parties and abuse of state media and other resources.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-12', 'Administrative problems marked the election in 2001, with three parties filing a legal petition challenging the election of ruling party candidate Levy MWANAWASA.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-13', 'MWANAWASA was reelected in 2006 in an election that was deemed free and fair.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-14', 'Upon his death in 2008, he was succeeded by his vice president, Rupiah BANDA, who won a special presidential byelection later that year.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-15', 'BANDA and the MMD lost to Michael SATA and the Patriotic Front (PF) in the 2011 general elections.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-16', 'SATA, however, presided over a period of haphazard economic management and attempted to silence opposition to PF policies.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-17', 'SATA died in 2014 and was succeeded by his vice president, Guy SCOTT, who served as interim president until 2015, when Edgar LUNGU won the presidential byelection and completed SATA''s term.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-18', 'LUNGU then won a full term in the 2016 presidential elections.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-2', 'The empire collapsed as a result of the growing slave trade and Portuguese incursions in the 16th and 17th centuries.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-3', 'The region was further influenced by migrants from the Zulu Kingdom to the south and the Luba and Lunda Kingdoms to the north, after invading colonial and African powers displaced local residents into the area around the Zambezi River, in what is now Zambia.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-4', 'In the 1880s, British companies began securing mineral and other economic concessions from local leaders.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-5', 'The companies eventually claimed control of the region and incorporated it as the protectorate of Northern Rhodesia in 1911.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-6', 'The UK took over administrative control from the British South Africa Company in 1924.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-7', 'During the 1920s and 1930s, advances in mining spurred British economic ventures and colonial settlement.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-8', 'Northern Rhodesia’s name was changed to Zambia upon independence from the UK in 1964, under independence leader and first President Kenneth KAUNDA.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-za-9', 'In the 1980s and 1990s, declining copper prices, economic mismanagement, and a prolonged drought hurt the economy.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZAMBIA"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/za/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/za/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-0', 'Harare is the capital of Zimbabwe.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-1', 'The hunter-gatherer San people first inhabited the area that eventually became Zimbabwe.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-10', 'A new constitution in 1961 further cemented White minority rule.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-11', 'In 1965, the government under White Prime Minister Ian SMITH unilaterally declared its independence from the UK.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-12', 'London did not recognize Rhodesia’s independence and demanded more voting rights for the Black majority in the country.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-13', 'International diplomacy and an uprising by Black Zimbabweans led to biracial elections in 1979 and independence (as Zimbabwe) in 1980.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-14', 'Robert MUGABE, who led the uprising and became the nation''s first prime minister, was the country''s only ruler (as president since 1987) from independence until 2017.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-15', 'In the mid-1980s, the government tortured and killed thousands of civilians in a crackdown on dissent known as the Gukurahundi campaign.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-16', 'Economic mismanagement and chaotic implementation of land redistribution policies periodically crippled the economy.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-17', 'General elections in 2002, 2008, and 2013 were severely flawed and widely condemned but allowed MUGABE to remain president.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-18', 'In 2017, Vice President Emmerson MNANGAGWA became president after a military intervention that forced MUGABE to resign, and MNANGAGWA cemented power by sidelining rival Grace MUGABE (Robert MUGABE’s wife).', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-19', 'In 2018, MNANGAGWA won the presidential election, and he has maintained the government''s longstanding practice of violently disrupting protests and politicizing institutions.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-2', 'These societies traded with Arab merchants on the Indian Ocean coast and organized under the Kingdom of Mapungubwe in the 11th century.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-3', 'A series of powerful trade-oriented Shona states succeeded Mapungubwe, including the Kingdom of Zimbabwe (ca.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-4', 'The Rozwi Empire expelled Portuguese colonists from the Zimbabwean plateau, but the Ndebele clan of Zulu King MZILIKAZI eventually conquered the area in 1838 during the era of conflict and population displacement known as the Mfecane.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-5', 'In the 1880s, colonists arrived with the British South Africa Company (BSAC) and obtained a written concession for mining rights from Ndebele King LOBENGULA.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-6', 'The king later disavowed the concession and accused the BSAC agents of deceit.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
insert into kb.anchors (anchor_id, text, state, packet, concepts, provenance, contributor, trust, license, source_url, revision) values ('enc-cia-zi-7', 'The BSAC annexed Mashonaland and then conquered Matabeleland during the First Matabele War of 1893-1894, establishing company rule over the territory.', 'anchor', '{"schema": "FORGE-RESONANCE-PACKET/v1", "Phi": 1, "eps": 0.0, "mu": 1.0, "sfe": {"Phi": 1, "eps": 0.0, "mu": 1.0}, "placed_by": "athena", "standing": "anchor", "phi_basis": "ingestion placement; factual anchor, phase Φ1"}'::jsonb, '["A.ZIMBABWE"]'::jsonb, '{"source": "cia-world-factbook", "source_url": "https://www.cia.gov/the-world-factbook/countries/zi/", "revision": "factbook.json", "license": "public-domain", "license_url": "https://www.cia.gov/the-world-factbook/about/copyright-and-contributors/", "terms": "https://www.usa.gov/government-works", "historical": false, "ingestion_note": "Sentence cut at ingestion from the CIA World Factbook. The factbook.json mirror is CC0. Recall does not segment text.", "contributor": "encyclopedia:cia-world-factbook"}'::jsonb, 'encyclopedia:cia-world-factbook', 'trusted', 'public-domain', 'https://www.cia.gov/the-world-factbook/countries/zi/', 'factbook.json') on conflict (anchor_id) do nothing;
